Here is a simple Python **exact-cover backtracking** solver for tiling an `H x W` board with T-tetrominoes.

It tries to place T-shapes until every cell is covered exactly once.

```python
def t_shapes():
    """
    Returns the 4 rotations of a T tetromino.
    Each shape is represented as offsets from an anchor cell.
    """
    return [
        [(0, 0), (0, 1), (0, 2), (1, 1)],   # T down
        [(1, 0), (1, 1), (1, 2), (0, 1)],   # T up
        [(0, 0), (1, 0), (2, 0), (1, 1)],   # T right
        [(0, 1), (1, 1), (2, 1), (1, 0)],   # T left
    ]


def generate_placements(h, w):
    placements = []

    for r in range(h):
        for c in range(w):
            for shape in t_shapes():
                cells = []
                ok = True

                for dr, dc in shape:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < h and 0 <= nc < w):
                        ok = False
                        break
                    cells.append((nr, nc))

                if ok:
                    placements.append(cells)

    return placements


def solve_t_tetromino(h, w):
    if (h * w) % 4 != 0:
        return None

    placements = generate_placements(h, w)

    # For each cell, store all placements that cover it.
    cell_to_placements = {}
    for i, placement in enumerate(placements):
        for cell in placement:
            cell_to_placements.setdefault(cell, []).append(i)

    uncovered = set((r, c) for r in range(h) for c in range(w))
    used = []

    def search():
        if not uncovered:
            return True

        # Choose the uncovered cell with the fewest possible placements.
        target = min(
            uncovered,
            key=lambda cell: sum(
                all(x in uncovered for x in placements[p])
                for p in cell_to_placements.get(cell, [])
            )
        )

        for p in cell_to_placements.get(target, []):
            placement = placements[p]

            if all(cell in uncovered for cell in placement):
                for cell in placement:
                    uncovered.remove(cell)

                used.append(placement)

                if search():
                    return True

                used.pop()

                for cell in placement:
                    uncovered.add(cell)

        return False

    if search():
        return used

    return None


def print_solution(h, w, solution):
    board = [["." for _ in range(w)] for _ in range(h)]

    for i, placement in enumerate(solution):
        mark = chr(ord("A") + (i % 26))
        for r, c in placement:
            board[r][c] = mark

    for row in board:
        print(" ".join(row))


# Example: 4x4 is tileable
h, w = 4, 4
solution = solve_t_tetromino(h, w)

if solution:
    print(f"{h}x{w} can be tiled.")
    print_solution(h, w, solution)
else:
    print(f"{h}x{w} cannot be tiled.")
```

Example output may look like:

```text
4x4 can be tiled.
A A A B
C A B B
C C B D
C D D D
```

To test `22 x 22`, change:

```python
h, w = 22, 22
```

But for `22 x 22`, pure search may be very slow. You should add the parity check before searching:

```python
def impossible_by_checkerboard(h, w):
    if (h * w) % 4 != 0:
        return True

    if h % 2 == 0 and w % 2 == 0:
        pieces = h * w // 4
        if pieces % 2 == 1:
            return True

    return False
```

Then:

```python
if impossible_by_checkerboard(22, 22):
    print("22x22 cannot be tiled.")
else:
    solution = solve_t_tetromino(22, 22)
```

For serious large-board solving, the stronger version is **Algorithm X / Dancing Links**, but this backtracking exact-cover version is easier to understand and works well for small boards.

